nodes.text_raw:
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  width: 1280px;
  height: 800px;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
}

.card {
  width: 1080px;
  min-height: 620px;
  background: rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 32px;
  padding: 56px 64px;
  color: #f0f0f5;
  box-shadow:
    0 32px 64px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  gap: 40px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.location {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.5px;
  color: #ffffff;
}

.date {
  font-size: 16px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.55);
  margin-top: 6px;
}

.condition-badge {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 14px 24px;
  font-size: 15px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.85);
}

.condition-icon {
  font-size: 28px;
  line-height: 1;
}

.temps {
  display: flex;
  align-items: baseline;
  gap: 48px;
}

.temp-main {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.temp-value {
  font-size: 96px;
  font-weight: 200;
  letter-spacing: -4px;
  color: #ffffff;
  line-height: 1;
}

.temp-unit {
  font-size: 32px;
  font-weight: 300;
  color: rgba(255, 255, 255, 0.5);
}

.temp-range {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.temp-range span {
  font-size: 18px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.6);
}

.temp-range .hi { color: #fbbf24; }
.temp-range .lo { color: #60a5fa; }

.hourly-section {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hourly-title {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: rgba(255, 255, 255, 0.4);
}

.hourly-chart {
  flex: 1;
  display: flex;
  align-items: flex-end;
  gap: 4px;
  padding-top: 24px;
  position: relative;
}

.hour-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  height: 100%;
  justify-content: flex-end;
}

.hour-bar-wrap {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  flex: 1;
}

.hour-bar {
  width: 28px;
  border-radius: 8px 8px 4px 4px;
  background: linear-gradient(180deg, rgba(251, 191, 36, 0.7) 0%, rgba(96, 165, 250, 0.5) 100%);
  transition: height 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  min-height: 4px;
}

.hour-temp {
  font-size: 12px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.8);
  white-space: nowrap;
}

.hour-label {
  font-size: 11px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.35);
}

.error-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex: 1;
  text-align: center;
}

.error-state .icon {
  font-size: 48px;
  opacity: 0.6;
}

.error-state .msg {
  font-size: 18px;
  color: rgba(255, 255, 255, 0.7);
  max-width: 400px;
  line-height: 1.5;
}

.loading-state {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1;
}

.spinner {
  width: 40px;
  height: 40px;
  border: 3px solid rgba(255, 255, 255, 0.15);
  border-top-color: rgba(255, 255, 255, 0.7);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

(function () {
  const params = new URLSearchParams(window.location.search);
  const lat = params.get('lat') || '52.52';
  const lon = params.get('lon') || '13.405';
  const name = params.get('name') || 'Berlin';

  const todayUTC = new Date().toISOString().slice(0, 10);
  const date = params.get('date') || todayUTC;

  const isPast = date < todayUTC;
  const endpoint = isPast ? '/api/om/archive' : '/api/om/forecast';

  const url = endpoint + '?' + new URLSearchParams({
    latitude: lat,
    longitude: lon,
    daily: 'temperature_2m_max,temperature_2m_min,weather_code',
    hourly: 'temperature_2m',
    timezone: 'UTC',
    temperature_unit: 'celsius',
    start_date: date,
    end_date: date
  }).toString();

  const WMO = {
    0: ['Clear sky', '\u2600\uFE0F'],
    1: ['Mainly clear', '\uD83C\uDF24\uFE0F'],
    2: ['Partly cloudy', '\u26C5'],
    3: ['Overcast', '\u2601\uFE0F'],
    45: ['Fog', '\uD83C\uDF2B\uFE0F'],
    48: ['Depositing rime fog', '\uD83C\uDF2B\uFE0F'],
    51: ['Light drizzle', '\uD83C\uDF26\uFE0F'],
    53: ['Moderate drizzle', '\uD83C\uDF26\uFE0F'],
    55: ['Dense drizzle', '\uD83C\uDF27\uFE0F'],
    56: ['Light freezing drizzle', '\uD83C\uDF28\uFE0F'],
    57: ['Dense freezing drizzle', '\uD83C\uDF28\uFE0F'],
    61: ['Slight rain', '\uD83C\uDF27\uFE0F'],
    63: ['Moderate rain', '\uD83C\uDF27\uFE0F'],
    65: ['Heavy rain', '\uD83C\uDF27\uFE0F'],
    66: ['Light freezing rain', '\uD83C\uDF28\uFE0F'],
    67: ['Heavy freezing rain', '\uD83C\uDF28\uFE0F'],
    71: ['Slight snowfall', '\uD83C\uDF28\uFE0F'],
    73: ['Moderate snowfall', '\uD83C\uDF28\uFE0F'],
    75: ['Heavy snowfall', '\u2744\uFE0F'],
    77: ['Snow grains', '\u2744\uFE0F'],
    80: ['Slight rain showers', '\uD83C\uDF26\uFE0F'],
    81: ['Moderate rain showers', '\uD83C\uDF27\uFE0F'],
    82: ['Violent rain showers', '\u26C8\uFE0F'],
    85: ['Slight snow showers', '\uD83C\uDF28\uFE0F'],
    86: ['Heavy snow showers', '\u2744\uFE0F'],
    95: ['Thunderstorm', '\u26C8\uFE0F'],
    96: ['Thunderstorm with slight hail', '\u26C8\uFE0F'],
    99: ['Thunderstorm with heavy hail', '\u26C8\uFE0F']
  };

  function conditionInfo(code) {
    return WMO[code] || ['Unknown', '\uD83C\uDF21\uFE0F'];
  }

  function formatDate(d) {
    const dt = new Date(d + 'T00:00:00Z');
    return dt.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' });
  }

  function renderError(msg) {
    document.getElementById('card').innerHTML =
      '<div class="error-state"><div class="icon">\u26A0\uFE0F</div><div class="msg">' + msg + '</div></div>';
  }

  function render(data) {
    const daily = data.daily;
    const hourly = data.hourly;

    if (!daily || !daily.temperature_2m_max || daily.temperature_2m_max.length === 0) {
      renderError('No weather data available for this date and location.');
      return;
    }

    const tMax = daily.temperature_2m_max[0];
    const tMin = daily.temperature_2m_min[0];
    const code = daily.weather_code[0];
    const [condText, condIcon] = conditionInfo(code);

    const hours = hourly.time || [];
    const temps = hourly.temperature_2m || [];

    const filteredTemps = [];
    const filteredHours = [];
    for (let i = 0; i < hours.length; i++) {
      if (hours[i].slice(0, 10) === date) {
        filteredTemps.push(temps[i]);
        filteredHours.push(hours[i]);
      }
    }

    const hTemps = filteredTemps.length ? filteredTemps : temps;
    const hHours = filteredHours.length ? filteredHours : hours;

    const minT = Math.min.apply(null, hTemps);
    const maxT = Math.max.apply(null, hTemps);
    const range = maxT - minT || 1;

    let hourlyHTML = '';
    for (let i = 0; i < hTemps.length; i++) {
      const pct = ((hTemps[i] - minT) / range) * 80 + 10;
      const hr = hHours[i] ? hHours[i].slice(11, 16) : '';
      const showLabel = i % 3 === 0 || i === hTemps.length - 1;
      hourlyHTML +=
        '<div class="hour-col">' +
          '<div class="hour-temp">' + Math.round(hTemps[i]) + '\u00B0</div>' +
          '<div class="hour-bar-wrap"><div class="hour-bar" style="height:' + pct + '%"></div></div>' +
          '<div class="hour-label">' + (showLabel ? hr : '') + '</div>' +
        '</div>';
    }

    document.getElementById('card').innerHTML =
      '<div class="header">' +
        '<div><div class="location">' + escapeHTML(name) + '</div>' +
        '<div class="date">' + formatDate(date) + '</div></div>' +
        '<div class="condition-badge"><span class="condition-icon">' + condIcon + '</span>' + condText + '</div>' +
      '</div>' +
      '<div class="temps">' +
        '<div class="temp-main"><span class="temp-value">' + Math.round(tMax) + '</span><span class="temp-unit">\u00B0C</span></div>' +
        '<div class="temp-range">' +
          '<span class="hi">\u2191 High ' + Math.round(tMax) + '\u00B0C</span>' +
          '<span class="lo">\u2193 Low ' + Math.round(tMin) + '\u00B0C</span>' +
        '</div>' +
      '</div>' +
      '<div class="hourly-section">' +
        '<div class="hourly-title">Hourly Temperature</div>' +
        '<div class="hourly-chart">' + hourlyHTML + '</div>' +
      '</div>';
  }

  function escapeHTML(s) {
    const d = document.createElement('div');
    d.textContent = s;
    return d.innerHTML;
  }

  fetch(url)
    .then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return res.json();
    })
    .then(render)
    .catch(function () {
      renderError('Unable to load weather data. Please check the location and date, then try again.');
    });
})();
